import{_ as a,o,c as t,am as n}from"./chunks/framework.CyAc67NY.js";const p=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),s={name:"glossaire.md"};function i(r,e,l,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>Modèle qui enchaîne lui-même des actions avec des tools, en boucle, jusqu&#39;à atteindre un objectif : c&#39;est la <strong>boucle agentique</strong> (modèle + tools + boucle + objectif, que le harness fait tourner). Les éditeurs utilisent aussi « agent » pour de simples assistants personnalisés.</p><h3 id="agent-de-code" tabindex="-1">Agent de code <a class="header-anchor" href="#agent-de-code" aria-label="Permalink to &quot;Agent de code&quot;">​</a></h3><p>Agent qui lit, modifie et exécute du code dans un dépôt (Copilot, Claude Code, Codex, Cursor…).</p><h3 id="boucle-agentique" tabindex="-1">Boucle agentique <a class="header-anchor" href="#boucle-agentique" aria-label="Permalink to &quot;Boucle agentique&quot;">​</a></h3><p>Le cycle demande → le modèle choisit un tool → le harness l&#39;exécute → le résultat entre dans le contexte → on recommence si besoin.</p><h3 id="compaction" tabindex="-1">Compaction <a class="header-anchor" href="#compaction" aria-label="Permalink to &quot;Compaction&quot;">​</a></h3><p>Résumé automatique ou demandé de la session pour libérer de la context window.</p><h3 id="context-rot" tabindex="-1">Context rot <a class="header-anchor" href="#context-rot" aria-label="Permalink to &quot;Context rot&quot;">​</a></h3><p>Dégradation des réponses quand la context window se remplit d&#39;ajouts, de corrections et d&#39;informations périmées ou contradictoires : la session reste crédible mais s&#39;éloigne du besoin initial.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="hook" tabindex="-1">Hook <a class="header-anchor" href="#hook" aria-label="Permalink to &quot;Hook&quot;">​</a></h3><p>Action déterministe déclenchée par le harness à un moment précis (avant une commande, après une édition), quoi que dise le modèle.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA <em>avant</em> qu&#39;elle soit utilisée.</p><h3 id="instructions-projet" tabindex="-1">Instructions projet <a class="header-anchor" href="#instructions-projet" aria-label="Permalink to &quot;Instructions projet&quot;">​</a></h3><p>Fichier versionné dans le dépôt, chargé à chaque session : conventions, commandes, pièges (<code>AGENTS.md</code>, <code>CLAUDE.md</code> pour Claude Code). C&#39;est l&#39;équivalent dev des instructions personnalisées.</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h3><p>Standard pour brancher de nouveaux tools sur un assistant : applications et données de l&#39;entreprise.</p><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><p>Les actions autorisées à l&#39;agent (lire, écrire, lancer une commande, accéder au réseau).</p><h3 id="plan-d-execution" tabindex="-1">Plan d&#39;exécution <a class="header-anchor" href="#plan-d-execution" aria-label="Permalink to &quot;Plan d&#39;exécution&quot;">​</a></h3><p>Liste d&#39;étapes vérifiables que l&#39;agent propose avant de coder, et que le dev corrige avant de le laisser faire.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h3><p>Savoir-faire emballé (consignes, modèles, exemples, parfois des scripts) que l&#39;assistant charge <strong>à la demande</strong>, quand la tâche correspond. Plus léger que des instructions permanentes, partageable dans une équipe. Claude parle d&#39;« Agent Skills » ; d&#39;autres assistants ont des équivalents.</p><h3 id="subagent" tabindex="-1">Subagent <a class="header-anchor" href="#subagent" aria-label="Permalink to &quot;Subagent&quot;">​</a></h3><p>Agent lancé par l&#39;agent principal pour une mission étroite, dans sa propre context window : il ne renvoie qu&#39;un résultat court, et la session principale reste légère.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (<em>tool calling</em>).</p>',37)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
